/**
 * Translate a key in the given interface language, interpolating {name}
 * placeholders from the optional params object.
 */
export function translate(language, key, params) {
  const lang = STRINGS[language] ? language : 'en';
  const dict = STRINGS[lang];
  let value = Object.prototype.hasOwnProperty.call(dict, key) ? dict[key] : key;
  if (params) {
    for (const [name, replacement] of Object.entries(params)) {
      value = value.replace(new RegExp(`\\{${name}\\}`, 'g'), String(replacement));
    }
  }
  return value;
}

/**
 * Display name for an alphabet id in the given interface language.
 */
export function alphabetDisplayName(language, alphabetId) {
  if (alphabetId === 'polish') return translate(language, 'alphabetPolish');
  if (alphabetId === 'nato') return translate(language, 'alphabetNato');
  return alphabetId;
}

/**
 * Display name for a mode id in the given interface language.
 */
export function modeDisplayName(language, modeId) {
  if (modeId === 'keyboard') return translate(language, 'modeKeyboard');
  if (modeId === 'suggestion') return translate(language, 'modeSuggestion');
  return modeId;
}

/**
 * The set of keys every language must define. Used by tests to keep the two
 * dictionaries in sync so no user-visible string is missing in either locale.
 */
export const REQUIRED_KEYS = Object.freeze(Object.keys(STRINGS.en));
