// Pure, framework-neutral domain logic for the Phonetic Benchmark v2 app.
//
// Everything in this module is side-effect free and takes any randomness as an
// injected `rng` argument so the behavior is fully testable without flaky
// assertions. The UI layer in main.js builds on top of these helpers.

/**
 * Fisher–Yates shuffle. Returns a new array; the input is not mutated.
 * `rng` defaults to Math.random and must return a float in [0, 1).
 */
export function shuffle(input, rng = Math.random) {
  const arr = Array.from(input);
  for (let i = arr.length - 1; i > 0; i--) {
    const j = Math.floor(rng() * (i + 1));
    const tmp = arr[i];
    arr[i] = arr[j];
    arr[j] = tmp;
  }
  return arr;
}

/**
 * Normalize a typed answer for comparison.
 *
 * - leading and trailing whitespace is ignored
 * - matching is case-insensitive
 * - diacritics remain significant (no folding, no normalization form stripping)
 *
 * The benchmark contract: `żaba` matches `ŻABA`, but `zaba` does NOT match
 * `ŻABA`. Plain `String.prototype.toLowerCase()` preserves Polish diacritics,
 * so it is the correct transform here. We deliberately avoid
 * `localeCompare({ sensitivity: 'base' })` or any NFD-stripping approach
 * because those would erase the diacritic distinction the benchmark requires.
 */
export function normalizeAnswer(input) {
  if (input === null || input === undefined) return '';
  return String(input).trim().toLowerCase();
}

/**
 * Decide whether a typed answer matches a target codeword under the
 * benchmark's keyboard-mode comparison rules.
 */
export function isCorrectAnswer(input, codeword) {
  return normalizeAnswer(input) === normalizeAnswer(codeword);
}

/**
 * Compute the final percentage score using the documented hint-based rule.
 *
 * `score_percent = round((clean_questions / total_questions) * 100)`
 * where `clean_questions = total_questions - hinted_questions`.
 *
 * A total of 0 yields 0 to avoid a NaN while still being harmless because the
 * benchmark alphabets always contain at least one symbol.
 */
export function computeScore(totalQuestions, hintedQuestions) {
  const total = Number(totalQuestions);
  const hinted = Number(hintedQuestions);
  if (!Number.isFinite(total) || total <= 0) return 0;
  const clean = total - hinted;
  return Math.round((clean / total) * 100);
}

/**
 * Build the four-option set for a suggestion-mode question.
 *
 * The fixed option array comes from `benchmark-data/multiple-choice-options.json`
 * and contains exactly one correct option (equal to the target codeword) and
 * three incorrect distractors. This function validates that contract and
 * returns the options in a shuffled display order.
 *
 * It never generates options ad hoc; it only shuffles the fixed data.
 */
export function buildQuestionOptions(fixedOptions, correctCodeword, rng = Math.random) {
  if (!Array.isArray(fixedOptions) || fixedOptions.length !== 4) {
    throw new Error('Suggestion-mode option set must contain exactly four options');
  }
  const target = normalizeAnswer(correctCodeword);
  const correctCount = fixedOptions.filter((opt) => normalizeAnswer(opt) === target).length;
  if (correctCount !== 1) {
    throw new Error(
      `Suggestion-mode option set must contain exactly one correct option, found ${correctCount}`
    );
  }
  return shuffle(fixedOptions, rng);
}

/**
 * Create a new exercise run: the full alphabet's entries in randomized order,
 * each appearing exactly once.
 *
 * Returns a frozen run description object. The UI layer owns mutable progress
 * state; this helper only captures the deterministic-per-rng plan.
 */
export function createRun(alphabetEntries, rng = Math.random) {
  if (!Array.isArray(alphabetEntries) || alphabetEntries.length === 0) {
    throw new Error('Cannot create a run from an empty alphabet');
  }
  const order = shuffle(alphabetEntries, rng);
  return Object.freeze({
    total: order.length,
    order: Object.freeze(order.map((e) => Object.freeze({ ...e })))
  });
}

/**
 * Validate that a run progress object satisfies the benchmark progression
 * contract: the run can only finish after every symbol is completed.
 */
export function isRunComplete(progress) {
  return progress.answered >= progress.total;
}
