// Canonical benchmark data loader.
//
// The application reads the phonetic alphabets and the fixed suggestion-mode
// option sets directly from the repository's `benchmark-data/` files. Those
// files are the benchmark's source of truth (see docs/REQUIREMENTS.md and
// docs/DECISIONS.md). Nothing here generates data ad hoc.

import alphabets from '../benchmark-data/alphabets.json' with { type: 'json' };
import multipleChoiceOptions from '../benchmark-data/multiple-choice-options.json' with { type: 'json' };

export const ALPHABETS = alphabets;
export const MULTIPLE_CHOICE_OPTIONS = multipleChoiceOptions;

export const ALPHABET_IDS = Object.freeze(['polish', 'nato']);
export const MODE_IDS = Object.freeze(['keyboard', 'suggestion']);
export const INTERFACE_LANGUAGES = Object.freeze(['pl', 'en']);

/**
 * Get the entries (`{ symbol, codeword }[]`) for a given alphabet id.
 */
export function getAlphabet(alphabetId) {
  if (!ALPHABET_IDS.includes(alphabetId)) {
    throw new Error(`Unknown alphabet id: ${alphabetId}`);
  }
  return ALPHABETS[alphabetId];
}

/**
 * Get the fixed four-option array for a symbol in a given alphabet.
 */
export function getOptionsForSymbol(alphabetId, symbol) {
  if (!ALPHABET_IDS.includes(alphabetId)) {
    throw new Error(`Unknown alphabet id: ${alphabetId}`);
  }
  const table = MULTIPLE_CHOICE_OPTIONS[alphabetId];
  if (!Object.prototype.hasOwnProperty.call(table, symbol)) {
    throw new Error(`No fixed option set for symbol ${symbol} in alphabet ${alphabetId}`);
  }
  const options = table[symbol];
  if (!Array.isArray(options) || options.length !== 4) {
    throw new Error(`Fixed option set for ${symbol} is malformed`);
  }
  return options;
}

/**
 * Validate the canonical data contract used by the app at startup.
 * Returns a list of human-readable violation strings (empty when OK).
 */
export function validateDataContract() {
  const violations = [];
  for (const id of ALPHABET_IDS) {
    const entries = ALPHABETS[id];
    if (!Array.isArray(entries) || entries.length === 0) {
      violations.push(`alphabet ${id} is missing or empty`);
      continue;
    }
    for (const entry of entries) {
      if (typeof entry.symbol !== 'string' || typeof entry.codeword !== 'string') {
        violations.push(`alphabet ${id} entry must use string symbol/codeword fields`);
        break;
      }
      const opts = MULTIPLE_CHOICE_OPTIONS[id]?.[entry.symbol];
      if (!Array.isArray(opts) || opts.length !== 4) {
        violations.push(`alphabet ${id} symbol ${entry.symbol} lacks a 4-option set`);
      } else if (!opts.includes(entry.codeword)) {
        violations.push(
          `alphabet ${id} symbol ${entry.symbol} option set missing codeword ${entry.codeword}`
        );
      }
    }
  }
  return violations;
}
