// Fixed attribution constants for the benchmark submission.
//
// Per docs/REQUIREMENTS.md, the implementation date MUST be a fixed date for
// the benchmark run. It must not be generated dynamically at runtime, at app
// startup, or at build time. These constants are the only source of that date.

export const BENCHMARK_AUTHOR = 'Piotr Kacała';
export const BENCHMARK_WEBSITE = 'piotrkacala.pl';
export const IMPLEMENTING_MODEL_NAME = 'GLM-5.2';
export const IMPLEMENTING_MODEL_VERSION = 'GLM-5.2 (opencode-go/glm-5.2)';
export const IMPLEMENTATION_DATE = '2026-06-23';

/**
 * Build the visible attribution line in the requested interface language.
 * The meaning is preserved in both languages; only the connector wording
 * changes.
 */
export function buildAttributionLine(language) {
  const lang = language === 'pl' ? 'pl' : 'en';
  if (lang === 'pl') {
    return `Phonetic Benchmark autorstwa ${BENCHMARK_AUTHOR} (${BENCHMARK_WEBSITE}). ` +
      `Zaimplementowane przez ${IMPLEMENTING_MODEL_VERSION} dnia ${IMPLEMENTATION_DATE}.`;
  }
  return `Phonetic Benchmark by ${BENCHMARK_AUTHOR} (${BENCHMARK_WEBSITE}). ` +
    `Developed by ${IMPLEMENTING_MODEL_VERSION} on ${IMPLEMENTATION_DATE}.`;
}
