// Phonetic Benchmark v2 — UI controller.
//
// Vanilla ESM JavaScript, no frontend framework. The app has three screens:
// setup, run, and result. The fixed attribution footer is always visible.
//
// Open product-question decisions (see README.md and
// docs/ai/IMPLEMENTATION_REPORT.md):
//   * Reset behavior: an "End run" control abandons the active run and returns
//     to setup. The result screen offers "New run" (back to setup) and
//     "Repeat same setup" (fresh shuffle, same settings).
//   * Interface-language switching is allowed on the setup and result screens
//     and is LOCKED during an active run, so the run's copy stays stable.

import {
  getAlphabet,
  getOptionsForSymbol,
  validateDataContract,
  ALPHABET_IDS,
  MODE_IDS,
  INTERFACE_LANGUAGES
} from './data.js';
import {
  shuffle,
  isCorrectAnswer,
  computeScore,
  buildQuestionOptions,
  createRun
} from './logic.js';
import {
  translate,
  alphabetDisplayName,
  modeDisplayName
} from './i18n.js';
import { buildAttributionLine } from './attribution.js';
import './style.css';

const app = document.getElementById('app');
const attributionEl = document.getElementById('attribution');

// Fixed application state. Only the fields below are mutable; transitions
// replace the `screen` value and re-render.
const state = {
  screen: 'setup',
  language: 'en',
  alphabetId: 'polish',
  modeId: 'keyboard',
  run: null,
  index: 0,
  hintedSet: new Set(),
  hintVisible: false,
  wrongFlash: false,
  lastSetup: null
};

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function t(key, params) {
  return translate(state.language, key, params);
}

function renderAttribution() {
  attributionEl.textContent = buildAttributionLine(state.language);
}

function render() {
  renderAttribution();
  if (state.screen === 'setup') renderSetup();
  else if (state.screen === 'run') renderRun();
  else if (state.screen === 'result') renderResult();
}

// ---------------------------------------------------------------------------
// Setup screen
// ---------------------------------------------------------------------------

function renderSetup() {
  const langOptions = INTERFACE_LANGUAGES.map((id) => {
    const label = id === 'pl' ? 'Polski' : 'English';
    const checked = state.language === id ? 'checked' : '';
    return `<label class="radio"><input type="radio" name="language" value="${id}" ${checked}/>${escapeHtml(label)}</label>`;
  }).join('');

  const alphabetOptions = ALPHABET_IDS.map((id) => {
    const checked = state.alphabetId === id ? 'checked' : '';
    return `<label class="radio"><input type="radio" name="alphabet" value="${id}" ${checked}/>${escapeHtml(alphabetDisplayName(state.language, id))}</label>`;
  }).join('');

  const modeOptions = MODE_IDS.map((id) => {
    const checked = state.modeId === id ? 'checked' : '';
    return `<label class="radio"><input type="radio" name="mode" value="${id}" ${checked}/>${escapeHtml(modeDisplayName(state.language, id))}</label>`;
  }).join('');

  app.innerHTML = `
    <section class="screen setup-screen">
      <h1 class="title">${escapeHtml(t('appTitle'))}</h1>
      <h2 class="heading">${escapeHtml(t('setupHeading'))}</h2>
      <div class="field">
        <span class="field-label">${escapeHtml(t('interfaceLanguageLabel'))}</span>
        <div class="radio-row">${langOptions}</div>
      </div>
      <div class="field">
        <span class="field-label">${escapeHtml(t('alphabetLabel'))}</span>
        <div class="radio-row">${alphabetOptions}</div>
      </div>
      <div class="field">
        <span class="field-label">${escapeHtml(t('modeLabel'))}</span>
        <div class="radio-row">${modeOptions}</div>
      </div>
      <p class="hint-note">${escapeHtml(t('setupHintNote'))}</p>
      <button id="start-btn" class="primary" type="button">${escapeHtml(t('startButton'))}</button>
    </section>
  `;

  app.querySelector('#start-btn').addEventListener('click', startRun);
  for (const input of app.querySelectorAll('input[name="language"]')) {
    input.addEventListener('change', (e) => {
      state.language = e.target.value;
      render();
    });
  }
  for (const input of app.querySelectorAll('input[name="alphabet"]')) {
    input.addEventListener('change', (e) => {
      state.alphabetId = e.target.value;
      render();
    });
  }
  for (const input of app.querySelectorAll('input[name="mode"]')) {
    input.addEventListener('change', (e) => {
      state.modeId = e.target.value;
      render();
    });
  }
}

function startRun() {
  const entries = getAlphabet(state.alphabetId);
  state.run = createRun(entries, Math.random);
  state.index = 0;
  state.hintedSet = new Set();
  state.hintVisible = false;
  state.wrongFlash = false;
  state.lastSetup = { language: state.language, alphabetId: state.alphabetId, modeId: state.modeId };
  state.screen = 'run';
  render();
}

// ---------------------------------------------------------------------------
// Run screen
// ---------------------------------------------------------------------------

function currentEntry() {
  return state.run.order[state.index];
}

function renderRun() {
  const entry = currentEntry();
  const total = state.run.total;
  const n = state.index + 1;
  const progressText = t('progress', { n, total });
  const promptText = state.modeId === 'keyboard' ? t('promptKeyboard') : t('promptSuggestion');
  const hintBlock = state.hintVisible
    ? `<p class="hint-revealed">${escapeHtml(t('hintRevealed', { codeword: entry.codeword }))}</p>`
    : '';
  const wrongBlock = state.wrongFlash ? `<p class="wrong-feedback">${escapeHtml(t('wrongFeedback'))}</p>` : '';

  let inputBlock;
  if (state.modeId === 'keyboard') {
    inputBlock = `
      <form id="keyboard-form" class="keyboard-form" autocomplete="off">
        <input id="answer-input" class="answer-input" type="text"
          placeholder="${escapeHtml(t('inputPlaceholder'))}"
          autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false" />
        <button class="primary" type="submit">${escapeHtml(t('checkButton'))}</button>
      </form>`;
  } else {
    const options = buildQuestionOptions(
      getOptionsForSymbol(state.alphabetId, entry.symbol),
      entry.codeword,
      Math.random
    );
    const buttons = options
      .map(
        (opt) =>
          `<button class="option-btn" type="button" data-option="${escapeHtml(opt)}">${escapeHtml(opt)}</button>`
      )
      .join('');
    inputBlock = `<div class="option-grid">${buttons}</div>`;
  }

  app.innerHTML = `
    <section class="screen run-screen">
      <header class="run-header">
        <h1 class="title">${escapeHtml(t('appTitle'))}</h1>
        <p class="progress">${escapeHtml(progressText)}</p>
        <p class="mode-tag">${escapeHtml(alphabetDisplayName(state.language, state.alphabetId))} · ${escapeHtml(modeDisplayName(state.language, state.modeId))}</p>
      </header>
      <div class="symbol-card">
        <p class="prompt">${escapeHtml(promptText)}</p>
        <p class="symbol" aria-label="symbol">${escapeHtml(entry.symbol)}</p>
        ${inputBlock}
        ${hintBlock}
        ${wrongBlock}
      </div>
      <div class="run-actions">
        <button id="hint-btn" class="ghost" type="button" ${state.hintVisible ? 'disabled' : ''}>${escapeHtml(t('hintButton'))}</button>
        <button id="end-run-btn" class="ghost danger" type="button">${escapeHtml(t('restartRunButton'))}</button>
      </div>
    </section>
  `;

  if (state.modeId === 'keyboard') {
    const form = app.querySelector('#keyboard-form');
    const input = app.querySelector('#answer-input');
    form.addEventListener('submit', (e) => {
      e.preventDefault();
      submitKeyboard(input.value);
    });
    input.focus();
  } else {
    for (const btn of app.querySelectorAll('.option-btn')) {
      btn.addEventListener('click', () => submitSuggestion(btn.dataset.option));
    }
  }

  app.querySelector('#hint-btn').addEventListener('click', useHint);
  app.querySelector('#end-run-btn').addEventListener('click', endRun);
}

function useHint() {
  state.hintedSet.add(state.index);
  state.hintVisible = true;
  state.wrongFlash = false;
  render();
}

function submitKeyboard(value) {
  const entry = currentEntry();
  if (isCorrectAnswer(value, entry.codeword)) {
    advance();
  } else {
    state.wrongFlash = true;
    render();
  }
}

function submitSuggestion(option) {
  const entry = currentEntry();
  if (isCorrectAnswer(option, entry.codeword)) {
    advance();
  } else {
    state.wrongFlash = true;
    render();
  }
}

function advance() {
  if (state.index + 1 >= state.run.total) {
    state.screen = 'result';
    state.wrongFlash = false;
    state.hintVisible = false;
    render();
  } else {
    state.index += 1;
    state.hintVisible = false;
    state.wrongFlash = false;
    render();
  }
}

function endRun() {
  state.run = null;
  state.screen = 'setup';
  render();
}

// ---------------------------------------------------------------------------
// Result screen
// ---------------------------------------------------------------------------

function renderResult() {
  const total = state.run.total;
  const hinted = state.hintedSet.size;
  const percent = computeScore(total, hinted);
  const context = t('resultContext', {
    alphabet: alphabetDisplayName(state.language, state.alphabetId),
    mode: modeDisplayName(state.language, state.modeId)
  });

  const langOptions = INTERFACE_LANGUAGES.map((id) => {
    const label = id === 'pl' ? 'Polski' : 'English';
    const checked = state.language === id ? 'checked' : '';
    return `<label class="radio"><input type="radio" name="language" value="${id}" ${checked}/>${escapeHtml(label)}</label>`;
  }).join('');

  app.innerHTML = `
    <section class="screen result-screen">
      <h1 class="title">${escapeHtml(t('appTitle'))}</h1>
      <h2 class="heading">${escapeHtml(t('resultHeading'))}</h2>
      <p class="score">${escapeHtml(t('resultScore', { percent }))}</p>
      <p class="result-context">${escapeHtml(context)}</p>
      <p class="result-hinted">${escapeHtml(t('resultHinted', { hinted, total }))}</p>
      <div class="field inline">
        <span class="field-label">${escapeHtml(t('interfaceLanguageLabel'))}</span>
        <div class="radio-row">${langOptions}</div>
      </div>
      <div class="result-actions">
        <button id="repeat-btn" class="primary" type="button">${escapeHtml(t('repeatSetupButton'))}</button>
        <button id="new-run-btn" class="ghost" type="button">${escapeHtml(t('newRunButton'))}</button>
      </div>
    </section>
  `;

  app.querySelector('#repeat-btn').addEventListener('click', () => {
    startRun();
  });
  app.querySelector('#new-run-btn').addEventListener('click', () => {
    state.run = null;
    state.screen = 'setup';
    render();
  });
  for (const input of app.querySelectorAll('input[name="language"]')) {
    input.addEventListener('change', (e) => {
      state.language = e.target.value;
      render();
    });
  }
}

// ---------------------------------------------------------------------------
// Boot
// ---------------------------------------------------------------------------

const violations = validateDataContract();
if (violations.length > 0) {
  // eslint-disable-next-line no-console
  console.error('Benchmark data contract violations:', violations);
  app.innerHTML = `<div class="error">Benchmark data contract violations: ${escapeHtml(violations.join('; '))}</div>`;
} else {
  render();
}
